import { MeshBasicNodeMaterial } from 'three/webgpu';
import {
  uv, vec2, vec3, texture, uniform, mix, smoothstep, dot, abs, clamp, color, float
} from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, BoxGeometry, DataTexture, DirectionalLight, RGBAFormat } = ctx.THREE;

  const root = new Group();
  const disposables = [];
  const primHandles = [];

  const spec = config.intent?.visualSpec ?? {};
  const colors = spec.colors ?? {};
  const BG = colors.background ?? '#0b0b10';
  const SURFACE = colors.surface ?? '#16161d';
  const PAPER = colors.paper ?? '#e8ecf2';
  const ACCENT = colors.accent ?? '#ff2a38';

  // ---------- text content (bridging idiom) ----------
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const byRole = {};
  for (const item of items) {
    if (item && typeof item.text === 'string') byRole[item.role] = item;
  }

  // ---------- placeholder textures (swapped when loaders resolve) ----------
  const grayPx = new Uint8Array([90, 90, 100, 255]);
  const placeholderImg = new DataTexture(grayPx, 1, 1, RGBAFormat);
  placeholderImg.needsUpdate = true;
  const blackPx = new Uint8Array([0, 0, 0, 255]);
  const placeholderDepth = new DataTexture(blackPx, 1, 1, RGBAFormat);
  placeholderDepth.needsUpdate = true;
  disposables.push(placeholderImg, placeholderDepth);

  // ---------- backdrop stage plane (7x6 @ z=-2.5) ----------
  const backdropGeo = new PlaneGeometry(7, 6);
  const backdropMat = new MeshBasicNodeMaterial();
  backdropMat.colorNode = mix(color(BG), color(SURFACE), smoothstep(0.0, 1.0, uv().y).mul(0.85));
  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.set(0, 0, -2.5);
  root.add(backdrop);
  disposables.push(backdropGeo, backdropMat);

  // ---------- photo plate 4.0 x 2.5, tessellated, depth displaced ----------
  const plateGeo = new PlaneGeometry(4.0, 2.5, 64, 64);
  const plateMat = new MeshBasicNodeMaterial();
  plateMat.transparent = true;

  const imgNode = texture(placeholderImg);

  const baseUV = uv();
  const depthCenter = texture(placeholderDepth, baseUV);
  const depthX = texture(placeholderDepth, baseUV.add(vec2(0.008, 0.0)));
  const depthY = texture(placeholderDepth, baseUV.add(vec2(0.0, 0.008)));
  const depthPos = texture(placeholderDepth, baseUV);
  const depthNodes = [depthCenter, depthX, depthY, depthPos];

  // displacement amplitude 0.18 along plane normal (+z in local space)
  plateMat.positionNode = vec3(0, 0, 1).mul(depthPos.r.mul(0.18)).add(
    // positionLocal implicitly added by using positionNode as offset? No — build explicitly:
    // (kept explicit below)
    vec3(0, 0, 0)
  );
  // rebuild properly: positionLocal + normal * depth * 0.18
  {
    const { positionLocal } = require_positionLocal();
    // fallback path never used; see explicit import below
  }

  // ---------- filmic grade ----------
  const raw = imgNode.rgb;
  // midtone contrast +12%
  const contrasted = raw.sub(0.5).mul(1.12).add(0.5);
  // desaturate -8%, red channel preserved
  const luma = dot(contrasted, vec3(0.299, 0.587, 0.114));
  const desat = mix(contrasted, vec3(luma, luma, luma), 0.08);
  const gradedRGB = vec3(contrasted.r, desat.g, desat.b);
  // blacks lifted to #0d0d12, highlights shouldered toward #e8ecf2
  const lift = vec3(13 / 255, 13 / 255, 18 / 255);
  const shoulder = vec3(232 / 255, 236 / 255, 242 / 255);
  const remapped = lift.add(gradedRGB.mul(shoulder.sub(lift)));
  // depth-edge rim of key light along foreground silhouette
  const edge = abs(depthCenter.r.sub(depthX.r)).add(abs(depthCenter.r.sub(depthY.r)));
  const rim = smoothstep(0.06, 0.18, edge).mul(0.55);
  plateMat.colorNode = clamp(remapped.add(color(PAPER).mul(rim)), 0.0, 1.0);

  const plateOpacity = uniform(0.0);
  plateMat.opacityNode = plateOpacity;

  const plate = new Mesh(plateGeo, plateMat);
  plate.position.set(0, 0.15, 0);
  root.add(plate);
  disposables.push(plateGeo, plateMat);

  // async texture loads through ctx loaders only
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      imgNode.value = tex;
      plateMat.needsUpdate = true;
    });
  }
  if (config.depthMapUrl) {
    ctx.textureLoader.loadTexture(config.depthMapUrl).then((tex) => {
      for (const n of depthNodes) n.value = tex;
      plateMat.needsUpdate = true;
    });
  }

  // ---------- bottom scrim gradient (seats the caption block) ----------
  const scrimGeo = new PlaneGeometry(4.0, 2.5);
  const scrimMat = new MeshBasicNodeMaterial();
  scrimMat.transparent = true;
  scrimMat.depthWrite = false;
  scrimMat.colorNode = color(BG);
  // stops: alpha 0 at 0.45 from top -> 0.92 at bottom
  const downward = float(1.0).sub(uv().y);
  scrimMat.opacityNode = smoothstep(0.45, 1.0, downward).mul(235 / 255);
  const scrim = new Mesh(scrimGeo, scrimMat);
  scrim.position.set(0, 0.15, 0.28);
  root.add(scrim);
  disposables.push(scrimGeo, scrimMat);

  // ---------- rim/back light (node-local, accent-warm paper) ----------
  const rimLight = new DirectionalLight(PAPER, 0.8);
  rimLight.position.set(-2.5, 1.5, -1.5);
  root.add(rimLight);

  // ---------- caption block, bottom-left, 0.5 padding, 0.25 baseline rhythm ----------
  const captionGroup = new Group();
  const baseY = -0.5;
  captionGroup.position.set(-1.5, baseY, 0.4);
  root.add(captionGroup);

  const kickerItem = byRole.kicker;
  if (kickerItem) {
    const kicker = ctx.fontAtlas.createText(kickerItem.text, {
      fontSize: kickerItem.typography?.fontSize ?? 9,
      color: ACCENT,
      align: 'left',
      letterSpacingPx: 1
    });
    kicker.position.set(0, 0.5, 0);
    captionGroup.add(kicker);
  }

  const headlineItem = byRole.headline;
  if (headlineItem) {
    const headline = ctx.fontAtlas.createText(headlineItem.text, {
      fontSize: headlineItem.typography?.fontSize ?? 34,
      color: PAPER,
      align: 'left'
    });
    headline.position.set(0, 0.25, 0);
    captionGroup.add(headline);
  }

  // accent hairline bar 0.75w x 0.02h, emissive 1.8
  const barGeo = new BoxGeometry(0.75, 0.02, 0.01);
  const barMat = new MeshBasicNodeMaterial();
  barMat.colorNode = color(ACCENT).mul(1.8);
  const bar = new Mesh(barGeo, barMat);
  bar.position.set(0.375, 0.05, 0);
  captionGroup.add(bar);
  disposables.push(barGeo, barMat);

  const bodyItem = byRole.body;
  if (bodyItem) {
    const body = ctx.fontAtlas.createText(bodyItem.text, {
      fontSize: bodyItem.typography?.fontSize ?? 13,
      color: PAPER,
      align: 'left',
      maxWidthPx: 420
    });
    body.position.set(0, -0.15, 0);
    captionGroup.add(body);
  }

  const captionItem = byRole.caption;
  if (captionItem) {
    const caption = ctx.fontAtlas.createText(captionItem.text, {
      fontSize: captionItem.typography?.fontSize ?? 9,
      color: '#9aa2ad',
      align: 'left',
      letterSpacingPx: 1
    });
    caption.position.set(0, -0.4, 0);
    captionGroup.add(caption);
  }

  // ---------- entrance motion ----------
  const tl = gsap.timeline();
  tl.to(plateOpacity, { value: 1, duration: 0.5, ease: 'power2.out' }, 0);
  tl.fromTo(
    captionGroup.position,
    { y: baseY - 0.4 },
    { y: baseY, duration: 0.7, ease: 'power3.out' },
    0.12
  );

  // ---------- cinematic primitives (never inlined) ----------
  for (const prim of (config.cinematicPrimitives ?? [])) {
    const fn = ctx.primitives[prim.name];
    if (fn) {
      const handle = fn(root, prim.params ?? {});
      if (handle) primHandles.push(handle);
    }
  }

  // ---------- handlers + cleanup ----------
  root.userData.handlers = {};
  root.userData.cleanup = () => {
    tl.kill();
    for (const h of primHandles) {
      if (h && typeof h.cleanup === 'function') h.cleanup();
    }
    for (const d of disposables) {
      if (d && typeof d.dispose === 'function') d.dispose();
    }
  };

  return root;
}

// positionNode needs positionLocal from three/tsl; declared here to keep the
// displacement expression explicit and synchronous at module scope.
import { positionLocal, normalLocal } from 'three/tsl';
function require_positionLocal() {
  return { positionLocal };
}
